from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
Right = Motor(Port.B, Direction.CLOCKWISE)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
motor = Motor(Port.E, Direction.CLOCKWISE)
motor_4 = Motor(Port.D, Direction.CLOCKWISE)
motor_5 = Motor(Port.C, Direction.CLOCKWISE)
motor_6 = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 54, 106)


# The main program starts here.
drive_base.straight(620)
drive_base.turn(-70)
drive_base.straight(420)
drive_base.turn(110)
drive_base.settings(straight_speed=100)
drive_base.straight(130)
